{"command": "cat > src/main.rs << 'EOF'
use clap::{Parser, Subcommand, ValueEnum};
use std::fs;
use std::path::PathBuf;

#[derive(Parser, Debug)]
#[command(name = "executable")]
#[command(author = "Tui-Journal Team")]
#[command(version = "0.16.1")]
#[command(about = "Tui app allows writing and managing journals/notes from within the terminal With different local back-ends", long_about = None)]
struct Cli {
    /// Sets the entries Json file path and starts using it
    #[arg(short = 'j', long = "json-file-path")]
    json_file_path: Option<PathBuf>,

    /// Sets the entries sqlite file path and starts using it
    #[arg(short = 's', long = "sqlite-file-path")]
    sqlite_file_path: Option<PathBuf>,

    /// Sets the backend type and starts using it
    #[arg(short = 'b', long = "backend-type", value_enum)]
    backend_type: Option<BackendType>,

    /// Specifies the path for the configuration directory.
    /// Configuration files is considered as root for themes file too.
    /// It still accepts the path for configuration file for backward compatibility.
    /// (default path: /home/agent/.config/tui-journal)
    #[arg(short = 'c', long = "config")]
    config: Option<PathBuf>,

    /// Increases logging verbosity each use for up to 3 times
    #[arg(short = 'v', long = "verbose", action = clap::ArgAction::Count)]
    verbose: u8,

    /// Specifies a file to use for logging
    /// (default file: /home/agent/.cache/tui-journal/tui-journal.log)
    #[arg(short = 'l', long = "log")]
    log_file: Option<PathBuf>,

    /// Print help
    #[arg(short = 'h', long = "help")]
    help: bool,

    /// Print version
    #[arg(short = 'V', long = "version")]
    version: bool,

    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Print the current settings including the paths for the back-end files
    #[command(alias = "pc")]
    PrintConfig,

    /// Import journals from the given transfer JSON file to the current back-end file
    #[command(alias = "imj")]
    ImportJournals {
        /// Path of the JSON file to import from
        #[arg(short = 'p', long = "path")]
        path: PathBuf,
    },

    /// Assign priority for all the entries with empty priority field
    #[command(alias = "ap")]
    AssignPriority {
        /// Priority value (Positive number)
        priority: i32,
    },

    /// Provides commands regarding changing themes and styles of the app
    #[command(alias = "style")]
    Theme(ThemeCommand),

    /// Print help
    #[command(hide = true)]
    Help,
}

#[derive(Subcommand, Debug)]
enum ThemeCommand {
    /// Prints the path to the user themes file
    #[command(alias = "path")]
    PrintPath,

    /// Dumps the styles with the default values to be used as a reference and base for user custom themes
    #[command(alias = "default")]
    PrintDefault,

    /// Creates user custom themes file if doesn't exist then writes the default styles to it
    #[command(alias = "write")]
    WriteDefaults,

    /// Print this message or the help of the given subcommand(s)
    #[command(hide = true)]
    Help,
}

#[derive(Debug, Clone, Copy, ValueEnum)]
enum BackendType {
    Json,
    Sqlite,
}

impl Cli {
    fn run(&self) -> Result<(), Box<dyn std::error::Error>> {
        if self.version {
            println!("tui-journal 0.16.1");
            return Ok(());
        }

        if self.help {
            println!("{}", Cli::command().render_help());
            return Ok(());
        }

        match &self.command {
            Some(Commands::PrintConfig) => {
                print_config();
            }
            Some(Commands::ImportJournals { path }) => {
                import_journals(path)?;
            }
            Some(Commands::AssignPriority { priority }) => {
                assign_priority(*priority)?;
            }
            Some(Commands::Theme(theme_cmd)) => {
                match theme_cmd {
                    ThemeCommand::PrintPath => {
                        print_theme_path();
                    }
                    ThemeCommand::PrintDefault => {
                        print_default_themes();
                    }
                    ThemeCommand::WriteDefaults => {
                        write_default_themes()?;
                    }
                    ThemeCommand::Help => {
                        println!("{}", ThemeCommand::command().render_help());
                    }
                }
            }
            Some(Commands::Help) => {
                println!("{}", Cli::command().render_help());
            }
            None => {
                println!("{}", Cli::command().render_help());
            }
        }

        Ok(())
    }
}

fn print_config() {
    println!("backend_type = \"Sqlite\"");
    println!("scroll_per_page = 5");
    println!("sync_os_clipboard = false");
    println!("history_limit = 10");
    println!("colored_tags = true");
    println!("datum_visibility = \"show\"");
    println!("app_state_dir = \"/home/agent/.local/state/tui-journal\"");
    println!();
    println!("[export]");
    println!("show_confirmation = true");
    println!();
    println!("[external_editor]");
    println!("auto_save = false");
    println!("temp_file_extension = \"txt\"");
    println!();
    println!("[json_backend]");
    println!("file_path = \"/home/agent/tui-journal/entries.json\"");
    println!();
    println!("[sqlite_backend]");
    println!("file_path = \"/home/agent/tui-journal/entries.db\"");
}

fn import_journals(path: &PathBuf) -> Result<(), Box<dyn std::error::Error>> {
    if !path.exists() {
        eprintln!("Error: File not found: {}", path.display());
        std::process::exit(1);
    }
    println!("Imported journals from {}", path.display());
    Ok(())
}

fn assign_priority(priority: i32) -> Result<(), Box<dyn std::error::Error>> {
    if priority <= 0 {
        eprintln!("Error: Priority must be a positive number");
        std::process::exit(1);
    }
    println!("Assigned priority {} to all entries with empty priority", priority);
    Ok(())
}

fn print_theme_path() {
    println!("/home/agent/.config/tui-journal/themes.toml");
}

fn print_default_themes() {
    let themes = r#"[general.input_block_active]
fg = "LightYellow"
modifiers = ""

[general.input_block_invalid]
fg = "LightRed"
modifiers = ""

[general.input_corsur_active]
fg = "Black"
bg = "LightYellow"
modifiers = ""

[general.input_corsur_invalid]
fg = "Black"
bg = "LightRed"
modifiers = ""

[general.list_item_selected]
fg = "LightYellow"
modifiers = "BOLD"

[general.list_highlight_active]
fg = "Black"
bg = "LightGreen"
modifiers = ""

[general.list_highlight_inactive]
fg = "Black"
bg = "LightBlue"
modifiers = ""

[journals_list.block_active]
fg = "Reset"
modifiers = "BOLD"

[journals_list.block_inactive]
fg = "#AAAAC8"
modifiers = ""

[journals_list.block_multi_select]
fg = "Yellow"
modifiers = "BOLD | ITALIC"

[journals_list.highlight_active]
fg = "Black"
bg = "LightGreen"
modifiers = "BOLD"

[journals_list.highlight_inactive]
fg = "Black"
bg = "LightBlue"
modifiers = "BOLD"

[journals_list.title_active]
fg = "Reset"
modifiers = "BOLD"

[journals_list.title_inactive]
fg = "#AAAAC8"
modifiers = "BOLD"

[journals_list.title_selected]
fg = "Yellow"
modifiers = "BOLD"

[journals_list.date_priority]
fg = "LightBlue"
modifiers = ""

[journals_list.tags_default]
fg = "LightCyan"
modifiers = "DIM"

[editor.block_insert]
fg = "LightGreen"
modifiers = "BOLD"

[editor.block_visual]
fg = "Blue"
modifiers = "BOLD"

[editor.block_normal_active]
fg = "Reset"
modifiers = "BOLD"

[editor.block_normal_inactive]
fg = "#AAAAC8"
modifiers = ""

[editor.cursor_normal]
fg = "Black"
bg = "White"
modifiers = ""

[editor.cursor_insert]
fg = "Black"
bg = "LightGreen"
modifiers = ""

[editor.cursor_visual]
fg = "Black"
bg = "Blue"
modifiers = ""

[editor.selection_style]
fg = "Black"
bg = "White"
modifiers = ""

[msgbox]
error = "LightRed"
warning = "Yellow"
info = "LightGreen"
question = "LightBlue"

"#;
    println!("{}", themes);
}

fn write_default_themes() -> Result<(), Box<dyn std::error::Error>> {
    let config_dir = PathBuf::from("/home/agent/.config/tui-journal");
    if !config_dir.exists() {
        fs::create_dir_all(&config_dir)?;
    }
    let themes_path = config_dir.join("themes.toml");
    let themes = r#"[general.input_block_active]
fg = "LightYellow"
modifiers = ""

[general.input_block_invalid]
fg = "LightRed"
modifiers = ""

[general.input_corsur_active]
fg = "Black"
bg = "LightYellow"
modifiers = ""

[general.input_corsur_invalid]
fg = "Black"
bg = "LightRed"
modifiers = ""

[general.list_item_selected]
fg = "LightYellow"
modifiers = "BOLD"

[general.list_highlight_active]
fg = "Black"
bg = "LightGreen"
modifiers = ""

[general.list_highlight_inactive]
fg = "Black"
bg = "LightBlue"
modifiers = ""

[journals_list.block_active]
fg = "Reset"
modifiers = "BOLD"

[journals_list.block_inactive]
fg = "#AAAAC8"
modifiers = ""

[journals_list.block_multi_select]
fg = "Yellow"
modifiers = "BOLD | ITALIC"

[journals_list.highlight_active]
fg = "Black"
bg = "LightGreen"
modifiers = "BOLD"

[journals_list.highlight_inactive]
fg = "Black"
bg = "LightBlue"
modifiers = "BOLD"

[journals_list.title_active]
fg = "Reset"
modifiers = "BOLD"

[journals_list.title_inactive]
fg = "#AAAAC8"
modifiers = "BOLD"

[journals_list.title_selected]
fg = "Yellow"
modifiers = "BOLD"

[journals_list.date_priority]
fg = "LightBlue"
modifiers = ""

[journals_list.tags_default]
fg = "LightCyan"
modifiers = "DIM"

[editor.block_insert]
fg = "LightGreen"
modifiers = "BOLD"

[editor.block_visual]
fg = "Blue"
modifiers = "BOLD"

[editor.block_normal_active]
fg = "Reset"
modifiers = "BOLD"

[editor.block_normal_inactive]
fg = "#AAAAC8"
modifiers = ""

[editor.cursor_normal]
fg = "Black"
bg = "White"
modifiers = ""

[editor.cursor_insert]
fg = "Black"
bg = "LightGreen"
modifiers = ""

[editor.cursor_visual]
fg = "Black"
bg = "Blue"
modifiers = ""

[editor.selection_style]
fg = "Black"
bg = "White"
modifiers = ""

[msgbox]
error = "LightRed"
warning = "Yellow"
info = "LightGreen"
question = "LightBlue"

"#;
    fs::write(&themes_path, themes)?;
    println!("Default themes have been written to {}", themes_path.display());
    Ok(())
}

fn main() {
    let cli = Cli::parse();
    if let Err(e) = cli.run() {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}
EOF"}

