fn print_help_for_command(command: &str) {
    match command {
        "print-config" | "pc" => print_print_config_help(),
        "import-journals" | "imj" => print_import_journals_help(),
        "assign-priority" | "ap" => print_assign_priority_help(),
        "theme" | "style" => print_theme_help(),
        "help" => print_help(),
        _ => {
            eprintln!("error: unrecognized subcommand '{}'", command);
            eprintln!();
            eprintln!("Usage: executable [OPTIONS] [COMMAND]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
}

fn print_help_for_theme_command(command: &str) {
    match command {
        "print-path" | "path" => {
            println!("Prints the path to the user themes file");
            println!();
            println!("Usage: executable theme print-path");
            println!();
            println!("Options:");
            println!("  -h, --help  Print help");
        }
        "print-default" | "default" => {
            println!("Dumps the styles with the default values to be used as a reference and base for user custom themes");
            println!();
            println!("Usage: executable theme print-default");
            println!();
            println!("Options:");
            println!("  -h, --help  Print help");
        }
        "write-defaults" | "write" => {
            println!("Creates user custom themes file if doesn't exist then writes the default styles to it");
            println!();
