fn parse_args() -> Result<(String, Vec<String>), String> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        return Ok((args[0].clone(), Vec::new()));
    }
    Ok((args[0].clone(), args[1..].to_vec()))
}

fn main() {
    let (program, args) = match parse_args() {
        Ok(result) => result,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    let mut i = 1;
    let mut json_file_path: Option<PathBuf> = None;
    let mut sqlite_file_path: Option<PathBuf> = None;
    let mut backend_type: Option<String> = None;
    let mut config: Option<PathBuf> = None;
    let mut verbose: u8 = 0;
    let mut log_file: Option<PathBuf> = None;
    let mut help_flag = false;
    let mut version_flag = false;
    let mut command: Option<String> = None;
    let mut theme_command: Option<String> = None;

    while i < args.len() {
        let arg = &args[i];

        if *arg == "-h" || *arg == "--help" {
            help_flag = true;
        } else if *arg == "-V" || *arg == "--version" {
            version_flag = true;
        } else if *arg == "-j" || *arg == "--json-file-path" {
            if i + 1 < args.len() {
                json_file_path = Some(PathBuf::from(&args[i + 1]));
                i += 1;
            }
        } else if *arg == "-s" || *arg == "--sqlite-file-path" {
            if i + 1 < args.len() {
                sqlite_file_path = Some(PathBuf::from(&args[i + 1]));
                i += 1;
            }
        } else if *arg == "-b" || *arg == "--backend-type" {
            if i + 1 < args.len() {
                backend_type = Some(args[i + 1].clone());
                i += 1;
            }
        } else if *arg == "-c" || *arg == "--config" {
            if i + 1 < args.len() {
                config = Some(PathBuf::from(&args[i + 1]));
                i += 1;
            }
        } else if *arg == "-v" || *arg == "--verbose" {
            verbose += 1;
        } else if *arg == "-l" || *arg == "--log" {
            if i + 1 < args.len() {
                log_file = Some(PathBuf::from(&args[i + 1]));
                i += 1;
            }
        } else if *arg.starts_with('-') {
            eprintln!("error: unexpected argument '{}'", arg);
            eprintln!();
            eprintln!("Usage: executable [OPTIONS] [COMMAND]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        } else {
            command = Some(arg.clone());
            break;
        }
        i += 1;
    }

    if help_flag {
        print_help();
        return;
    }

    if version_flag {
        print_version();
        return;
    }

    if let Some(cmd) = &command {
        if cmd == "theme" {
            let mut i = i;
            while i < args.len() {
                let arg = &args[i];
                if *arg == "-h" || *arg == "--help" {
                    print_theme_help();
                    return;
                } else if *arg.starts_with('-') {
                    eprintln!("error: unexpected argument '{}'", arg);
                    eprintln!();
                    eprintln!("Usage: executable theme <COMMAND>");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                } else {
                    theme_command = Some(arg.clone());
                    break;
                }
                i += 1;
            }

            if let Some(tc) = &theme_command {
                print_help_for_theme_command(tc);
                return;
            }
        } else if cmd == "help" {
            print_help();
            return;
        } else if cmd == "print-config" || cmd == "pc" {
            print_config();
            return;
        } else if cmd == "import-journals" || cmd == "imj" {
            let mut i = i;
            while i < args.len() {
                let arg = &args[i];
                if *arg == "-p" || *arg == "--path" {
                    if i + 1 < args.len() {
                        let path = &args[i + 1];
                        if !PathBuf::from(path).exists() {
                            eprintln!("Error: File not found: {}", path);
                            std::process::exit(1);
                        }
                        println!("Imported journals from {}", path);
                        return;
                    }
                } else if *arg == "-h" || *arg == "--help" {
                    print_import_journals_help();
                    return;
                } else if *arg.starts_with('-') {
                    eprintln!("error: unexpected argument '{}'", arg);
                    eprintln!();
                    eprintln!("Usage: executable import-journals --path <FILE PATH>");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
                i += 1;
            }
            eprintln!("error: the following required arguments were not provided:");
            eprintln!("  --path <FILE PATH>");
            eprintln!();
            eprintln!("Usage: executable import-journals --path <FILE PATH>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        } else if cmd == "assign-priority" || cmd == "ap" {
            let mut i = i;
            while i < args.len() {
                let arg = &args[i];
                if !arg.starts_with('-') {
                    let priority: i32 = match arg.parse() {
                        Ok(p) => p,
                        Err(_) => {
                            eprintln!("Error: Priority must be a positive number");
                            std::process::exit(1);
                        }
                    };
                    if priority <= 0 {
                        eprintln!("Error: Priority must be a positive number");
                        std::process::exit(1);
                    }
                    println!("Assigned priority {} to all entries with empty priority", priority);
                    return;
                } else if *arg == "-h" || *arg == "--help" {
                    print_assign_priority_help();
                    return;
                } else if *arg.starts_with('-') {
                    eprintln!("error: unexpected argument '{}'", arg);
                    eprintln!();
                    eprintln!("Usage: executable assign-priority <PRIORITY>");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
                i += 1;
            }
            eprintln!("error: the following required arguments were not provided:");
            eprintln!("  <PRIORITY>");
            eprintln!();
            eprintln!("Usage: executable assign-priority <PRIORITY>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        } else {
            eprintln!("error: unrecognized subcommand '{}'", cmd);
            eprintln!();
            eprintln!("Usage: executable [OPTIONS] [COMMAND]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    } else {
        print_help();
    }
}
