        let arg = &args[i];

        if arg == "-h" || arg == "--help" {
            help_flag = true;
        } else if arg == "-V" || arg == "--version" {
            version_flag = true;
        } else if arg.starts_with('-') {
            eprintln!("error: unexpected argument '{}'", arg);
            eprintln!();
            eprintln!("Usage: executable [OPTIONS] [COMMAND]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        } else {
            command = Some(arg.clone());
            break;
        }
        i += 1;
    }

    if help_flag {
        print_help();
        return;
    }

    if version_flag {
        print_version();
        return;
    }

    if let Some(cmd) = &command {
        if cmd == "theme" {
            let mut i = i;
            while i < args.len() {
                let arg = &args[i];
                if arg == "-h" || arg == "--help" {
