            let mut i = i;
            while i < args.len() {
                let arg = &args[i];
                if arg == "-p" || arg == "--path" {
                    if i + 1 < args.len() {
                        let path = &args[i + 1];
                        if !PathBuf::from(path).exists() {
                            eprintln!("Error: File not found: {}", path);
