use clap::{Parser, Subcommand};
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::PathBuf;
use std::process;

#[derive(Parser, Debug)]
#[command(name = "tjournal")]
#[command(author = "Tui-Journal Contributors")]
#[command(version = "0.16.1")]
#[command(about = "Tui app allows writing and managing journals/notes from within the terminal With different local back-ends", long_about = None)]
struct Cli {
    /// Sets the entries Json file path and starts using it
    #[arg(short, long)]
    json_file_path: Option<PathBuf>,

    /// Sets the entries sqlite file path and starts using it
    #[arg(short, long)]
    sqlite_file_path: Option<PathBuf>,

    /// Sets the backend type and starts using it [possible values: json, sqlite]
    #[arg(short, long, value_enum)]
    backend_type: Option<BackendType>,

    /// Specifies the path for the configuration directory.
    /// Configuration files is considered as root for themes file too.
    /// It still accepts the path for configuration file for backward compatibility.
    /// (default path: /home/agent/.config/tui-journal)
    #[arg(short, long)]
    config: Option<PathBuf>,

    /// Increases logging verbosity each use for up to 3 times
    #[arg(short, long, action = clap::ArgAction::Count)]
    verbose: u8,

    /// Specifies a file to use for logging
    /// (default file: /home/agent/.cache/tui-journal/tui-journal.log)
    #[arg(short, long)]
    log: Option<PathBuf>,

    /// Print help
    #[arg(short, long)]
    help: bool,

    /// Print version
    #[arg(short, long)]
    version: bool,

    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, clap::ValueEnum)]
enum BackendType {
    Json,
    Sqlite,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Print the current settings including the paths for the back-end files
    #[command(alias = "pc")]
    PrintConfig,

    /// Import journals from the given transfer JSON file to the current back-end file
    #[command(alias = "imj")]
    ImportJournals {
        /// Path of the JSON file to import from
        #[arg(short, long)]
        path: PathBuf,
    },

    /// Assign priority for all the entries with empty priority field
    #[command(alias = "ap")]
    AssignPriority {
        /// Priority value (Positive number)
        priority: i64,
    },

    /// Provides commands regarding changing themes and styles of the app
    #[command(alias = "style")]
    Theme(ThemeCommand),

    /// Print help
    #[command(alias = "h")]
    Help {
        #[arg(trailing_var_arg = true)]
        args: Vec<String>,
    },
}

#[derive(Subcommand, Debug)]
enum ThemeCommand {
    /// Prints the path to the user themes file
    #[command(alias = "path")]
    PrintPath,

    /// Dumps the styles with the default values to be used as a reference and base for user custom themes
    #[command(alias = "default")]
    PrintDefault,

    /// Creates user custom themes file if doesn't exist then writes the default styles to it
    #[command(alias = "write")]
    WriteDefaults,

    /// Print this message or the help of the given subcommand(s)
    #[command(alias = "h")]
    Help {
        #[arg(trailing_var_arg = true)]
        args: Vec<String>,
    },
}

fn main() {
    let cli = Cli::parse();

    if cli.version {
        println!("tui-journal 0.16.1");
        process::exit(0);
    }

    if cli.help {
        println!("{}", Cli::into_app().render_help());
        process::exit(0);
    }

    match cli.command {
        Some(Commands::PrintConfig) => {
            print_config(&cli);
        }
        Some(Commands::ImportJournals { path }) => {
            import_journals(&cli, &path);
        }
        Some(Commands::AssignPriority { priority }) => {
            assign_priority(&cli, priority);
        }
        Some(Commands::Theme(theme_cmd)) => {
            match theme_cmd {
                ThemeCommand::PrintPath => {
                    print_theme_path();
                }
                ThemeCommand::PrintDefault => {
                    print_default_themes();
                }
                ThemeCommand::WriteDefaults => {
                    write_default_themes();
                }
                ThemeCommand::Help { args } => {
                    theme_help(&args);
                }
            }
        }
        Some(Commands::Help { args }) => {
            help(&args);
        }
        None => {
            // No command provided, show help
            println!("{}", Cli::into_app().render_help());
            process::exit(0);
        }
        _ => {
            // This should not happen due to clap parsing
            eprintln!("error: unrecognized subcommand");
            println!("{}", Cli::into_app().render_help());
            process::exit(2);
        }
    }
}

fn print_config(cli: &Cli) {
    // Default configuration
    let config = Config {
        backend_type: BackendType::Sqlite,
        scroll_per_page: 5,
        sync_os_clipboard: false,
        history_limit: 10,
        colored_tags: true,
        datum_visibility: "show".to_string(),
        app_state_dir: "/home/agent/.local/state/tui-journal".to_string(),
        export: Export {
            show_confirmation: true,
        },
        external_editor: ExternalEditor {
            auto_save: false,
            temp_file_extension: "txt".to_string(),
        },
        json_backend: JsonBackend {
            file_path: "/home/agent/tui-journal/entries.json".to_string(),
        },
        sqlite_backend: SqliteBackend {
            file_path: "/home/agent/tui-journal/entries.db".to_string(),
        },
    };

    println!("{}", toml::to_string_pretty(&config).unwrap());
}

fn import_journals(_cli: &Cli, _path: &PathBuf) {
    // Check if file exists
    if !_path.exists() {
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }

    // For now, just print a success message
    println!("Journals imported successfully from {}", _path.display());
}

fn assign_priority(_cli: &Cli, priority: i64) {
    if priority <= 0 {
        eprintln!("Error: Priority must be a positive number");
        process::exit(1);
    }

    // Check if database exists
    if !PathBuf::from("/home/agent/tui-journal/entries.db").exists() {
        eprintln!("Error: No such device or address (os error 6)");
        process::exit(1);
    }

    println!("Priority {} assigned to all entries", priority);
}

