    /// Print this message or the help of the given subcommand(s)
    #[command(alias = "h")]
    Help {
        #[arg(trailing_var_arg = true)]
        args: Vec<String>,
    },
}

fn main() {
    let cli = Cli::parse();

    if cli.version {
        println!("tui-journal 0.16.1");
        process::exit(0);
    }

    if cli.help {
        println!("{}", Cli::into_app().render_help());
        process::exit(0);
    }

    match cli.command {
        Some(Commands::PrintConfig) => {
            print_config(&cli);
        }
        Some(Commands::ImportJournals { path }) => {
            import_journals(&cli, &path);
        }
        Some(Commands::AssignPriority { priority }) => {
            assign_priority(&cli, priority);
        }
        Some(Commands::Theme(theme_cmd)) => {
            match theme_cmd {
                ThemeCommand::PrintPath => {
                    print_theme_path();
                }
                ThemeCommand::PrintDefault => {
                    print_default_themes();
                }
                ThemeCommand::WriteDefaults => {
                    write_default_themes();
                }
                ThemeCommand::Help { args } => {
                    theme_help(&args);
                }
            }
        }
        Some(Commands::Help { args }) => {
            help(&args);
        }
        None => {
            // No command provided, show help
            println!("{}", Cli::into_app().render_help());
            process::exit(0);
        }
        _ => {
            // This should not happen due to clap parsing
            eprintln!("error: unrecognized subcommand");
            println!("{}", Cli::into_app().render_help());
            process::exit(2);
        }
    }
}

