        if args.len() > 1 {
            let subcmd = &args[1];
            match subcmd.as_str() {
                "print-path" => {
                    println!("Prints the path to the user themes file\n\nUsage: tjournal theme print-path\n\nOptions:\n  -h, --help  Print help");
                }
                "print-default" => {
                    println!("Dumps the styles with the default values to be used as a reference and base for user custom themes\n\nUsage: tjournal theme print-default\n\nOptions:\n  -h, --help  Print help");
                }
                "write-defaults" => {
                    println!("Creates user custom themes file if doesn't exist then writes the default styles to it\n\nUsage: tjournal theme write-defaults\n\nOptions:\n  -h, --help  Print help");
                }
                "write" => {
                    println!("Creates user custom themes file if doesn't exist then writes the default styles to it\n\nUsage: tjournal theme write-defaults\n\nOptions:\n  -h, --help  Print help");
                }
